package com.sahilprojects.bettingApp.participation;

import java.time.Instant;

/**
 * What ParticipationService needs from a league member or a standalone contest participant.
 * Both have the same six statuses and the same workflow, so the rules are written once.
 * Implemented by LeagueMember and ContestParticipant. The setters are generated by Lombok on those classes.
 */
public interface Participation {

    Long getId();

    ParticipationKind kind();

    /** For audit entries. Null when the participation is in a standalone contest. */
    Long leagueIdForAudit();

    /** For audit entries. Null for a league member. */
    Long contestIdForAudit();

    Long participantUserId();

    String currentStatus();

    /** Throws IllegalArgumentException when the name is not a status of this participation. */
    void changeStatus(String newStatus);

    /** True when the money is paid. For a league contest, where nothing is paid separately, this is always true. */
    boolean isPaid();

    void recordPaid(Instant at);

    void recordUnpaid();

    void setConfirmedAt(Instant at);

    void setRemovedAt(Instant at);

    void setStatusReason(String reason);
}
